"""PHP · referencia completa (etapas 6 y 7)."""
from .tabla import filas

E6 = filas(r"""
Funciones de texto strlen y strtoupper ¦ strtoupper ¦ funciones para medir y cambiar textos ¦ mostrar un nombre en mayúsculas ¦ <?php⏎$n = "ana";⏎echo strtoupper($n), " ", strlen($n); ¦ muestra ANA 3 ¦ usar strlen con tildes; para eso está mb_strlen
Funciones multibyte ¦ mb_strlen ¦ funciones de texto que entienden tildes y eñes ¦ contar bien las letras de «canción» ¦ <?php⏎echo strlen("canción"), " ", mb_strlen("canción"); ¦ muestra 8 y 7 ¦ cortar textos con substr y romper las tildes
explode e implode ¦ explode ¦ funciones para separar textos y unir arreglos ¦ procesar una línea CSV ¦ <?php⏎$p = explode(",", "ana,luis,bea");⏎echo implode(" | ", $p); ¦ separa por comas y une con barras ¦ invertir el orden de los argumentos de explode
str_replace y sprintf ¦ sprintf ¦ funciones para reemplazar texto y dar formato ¦ mostrar un precio con dos decimales ¦ <?php⏎echo sprintf("Total: $%.2f", 12.5), " ", str_replace("-", " ", "hola-mundo"); ¦ formatea el precio y cambia guiones ¦ concatenar números sin formato
number_format ¦ number_format ¦ función que da formato a números con miles ¦ mostrar precios en pesos ¦ <?php⏎echo number_format(1234567.891, 2, ",", "."); ¦ muestra 1.234.567,89 ¦ olvidar indicar los separadores colombianos
trim, ucfirst y str_pad ¦ str_pad ¦ funciones para limpiar y rellenar textos ¦ mostrar códigos con ceros a la izquierda ¦ <?php⏎echo ucfirst(trim("  hola ")), " ", str_pad("7", 3, "0", STR_PAD_LEFT); ¦ limpia y rellena con ceros ¦ guardar en la base los textos sin limpiar
array_map y array_filter ¦ array_filter ¦ funciones para transformar y filtrar arreglos ¦ quedarse con los números pares duplicados ¦ <?php⏎$n = [1, 2, 3, 4];⏎print_r(array_map(fn($x) => $x * 2, array_filter($n, fn($x) => $x % 2 == 0))); ¦ filtra pares y los duplica ¦ olvidar que array_filter conserva las claves originales
array_reduce y array_sum ¦ array_sum ¦ funciones para acumular valores ¦ calcular el total de un carrito ¦ <?php⏎$p = [10, 20, 30];⏎echo array_sum($p), " ", array_reduce($p, fn($a, $x) => max($a, $x), 0); ¦ suma y busca el mayor ¦ hacer bucles manuales para sumar
sort, usort y ksort ¦ usort ¦ funciones para ordenar arreglos ¦ ordenar productos por precio ¦ <?php⏎$p = [["n" => "a", "p" => 5], ["n" => "b", "p" => 2]];⏎usort($p, fn($x, $y) => $x["p"] <=> $y["p"]);⏎echo $p[0]["n"]; ¦ ordena del más barato al más caro ¦ esperar que sort devuelva el arreglo, cuando devuelve true
Operador nave espacial ¦ <=> ¦ operador que compara y devuelve -1, 0 o 1 ¦ ordenar con usort de forma corta ¦ <?php⏎echo 1 <=> 2, " ", 2 <=> 2, " ", 3 <=> 2; ¦ muestra -1 0 1 ¦ restar valores y fallar con textos
array_keys, array_values y array_column ¦ array_column ¦ funciones para sacar claves, valores o una columna ¦ obtener los nombres de una lista de usuarios ¦ <?php⏎$u = [["id" => 1, "n" => "Ana"], ["id" => 2, "n" => "Luis"]];⏎print_r(array_column($u, "n", "id")); ¦ crea un arreglo id → nombre ¦ recorrer con foreach para sacar una sola columna
array_slice y array_splice ¦ array_slice ¦ funciones para tomar o quitar partes de un arreglo ¦ paginar resultados ¦ <?php⏎$n = range(1, 10);⏎print_r(array_slice($n, 3, 3)); ¦ toma los elementos 4, 5 y 6 ¦ confundir slice, que copia, con splice, que modifica
array_search y array_key_exists ¦ array_key_exists ¦ funciones para buscar valores y claves ¦ saber si un usuario tiene correo ¦ <?php⏎$u = ["nombre" => "Ana", "correo" => null];⏎var_dump(array_key_exists("correo", $u), isset($u["correo"])); ¦ muestra que la clave existe aunque sea null ¦ usar isset y fallar con valores null
compact y extract ¦ compact ¦ funciones que pasan variables a arreglos y al revés ¦ enviar datos a una vista ¦ <?php⏎$nombre = "Ana"; $edad = 20;⏎print_r(compact("nombre", "edad")); ¦ arma un arreglo con las variables ¦ usar extract con datos del usuario y pisar variables
Fechas con date y strtotime ¦ strtotime ¦ funciones para dar formato y calcular fechas ¦ calcular la fecha de vencimiento ¦ <?php⏎echo date("d/m/Y", strtotime("2026-12-01 +30 days")); ¦ suma 30 días a la fecha ¦ olvidar configurar la zona horaria
DateInterval ¦ diff ¦ objeto para calcular diferencias entre fechas ¦ calcular la edad de una persona ¦ <?php⏎$n = new DateTime("2007-05-10"); $hoy = new DateTime("2026-12-01");⏎echo $n->diff($hoy)->y, " años"; ¦ calcula la edad en años ¦ restar timestamps y fallar con años bisiestos
Expresiones regulares en PHP ¦ preg_match ¦ funciones para validar y buscar patrones ¦ validar una placa de carro ¦ <?php⏎var_dump(preg_match('/^[A-Z]{3}\d{3}$/', "ABC123") === 1); ¦ valida el formato de la placa ¦ olvidar los delimitadores del patrón
Superglobales ¦ $_GET ¦ arreglos con los datos de la petición ¦ leer el parámetro de búsqueda de la URL ¦ <?php⏎$q = $_GET["q"] ?? "nada";⏎echo "Buscaste: " . htmlspecialchars($q); ¦ lee el parámetro q y lo muestra seguro ¦ mostrar los datos sin escapar
Subir archivos ¦ $_FILES ¦ arreglo con los archivos enviados por formulario ¦ guardar la foto de perfil ¦ <?php⏎// if ($_FILES["foto"]["error"] === UPLOAD_ERR_OK)⏎//   move_uploaded_file($_FILES["foto"]["tmp_name"], "subidas/" . bin2hex(random_bytes(8)) . ".jpg");⏎echo "subida"; ¦ guarda el archivo con un nombre aleatorio ¦ guardar el archivo con el nombre que envió el usuario
Cookies en PHP ¦ setcookie ¦ función para guardar datos pequeños en el navegador ¦ recordar el idioma del usuario ¦ <?php⏎setcookie("idioma", "es", ["expires" => time() + 86400 * 365, "httponly" => true, "samesite" => "Lax"]);⏎echo "cookie"; ¦ guarda el idioma por un año ¦ enviar la cookie después de imprimir contenido
""")

E7 = filas(r"""
PDO ¦ PDO ¦ clase para conectarse a bases de datos de forma segura ¦ consultar MySQL desde PHP ¦ <?php⏎$db = new PDO("sqlite::memory:");⏎$db->exec("CREATE TABLE t (n TEXT)");⏎$db->prepare("INSERT INTO t VALUES (?)")->execute(["Ana"]);⏎echo $db->query("SELECT n FROM t")->fetchColumn(); ¦ crea, inserta y consulta con PDO ¦ concatenar variables dentro del SQL
Modos de error de PDO ¦ ERRMODE_EXCEPTION ¦ configuración para que PDO lance excepciones ¦ enterarte de los errores de la base de datos ¦ <?php⏎$db = new PDO("sqlite::memory:", null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);⏎try { $db->query("SELECT * FROM nada"); } catch (PDOException $e) { echo "Error de BD"; } ¦ atrapa el error de la consulta ¦ mostrar el mensaje del error al usuario final
Transacciones con PDO ¦ beginTransaction ¦ agrupar varias consultas para que pasen todas o ninguna ¦ transferir dinero entre cuentas ¦ <?php⏎$db = new PDO("sqlite::memory:");⏎$db->beginTransaction();⏎$db->exec("CREATE TABLE c (s INT)");⏎$db->commit();⏎echo "ok"; ¦ confirma las consultas juntas ¦ olvidar el rollBack en el catch
password_hash ¦ password_hash ¦ funciones para guardar y verificar contraseñas ¦ crear un inicio de sesión seguro ¦ <?php⏎$h = password_hash("secreta123", PASSWORD_DEFAULT);⏎var_dump(password_verify("secreta123", $h)); ¦ cifra y verifica la contraseña ¦ guardar contraseñas con md5
Tokens CSRF ¦ csrf ¦ código secreto que protege formularios de envíos falsos ¦ evitar que otra página envíe tu formulario ¦ <?php⏎session_start();⏎$_SESSION["csrf"] ??= bin2hex(random_bytes(32));⏎echo '<input type="hidden" name="csrf" value="' . $_SESSION["csrf"] . '">'; ¦ agrega un token secreto al formulario ¦ no comparar el token con hash_equals
Cabeceras HTTP ¦ header ¦ función que envía cabeceras como redirecciones o tipo de contenido ¦ redirigir después de guardar un formulario ¦ <?php⏎// header("Location: /gracias.php"); exit;⏎header("Content-Type: application/json");⏎echo json_encode(["ok" => true]); ¦ responde con JSON ¦ olvidar exit después de redirigir
API REST con PHP ¦ $_SERVER["REQUEST_METHOD"] ¦ responder JSON según el método de la petición ¦ crear una API sencilla sin framework ¦ <?php⏎header("Content-Type: application/json");⏎$metodo = $_SERVER["REQUEST_METHOD"] ?? "GET";⏎echo json_encode(["metodo" => $metodo, "datos" => []]); ¦ responde JSON según el método ¦ no devolver códigos de estado correctos
Leer el cuerpo JSON ¦ php://input ¦ forma de leer el JSON que envía fetch ¦ recibir datos de una app de JavaScript ¦ <?php⏎$datos = json_decode(file_get_contents("php://input") ?: "{}", true);⏎echo json_encode(["recibido" => $datos]); ¦ lee el JSON enviado ¦ buscar los datos JSON en $_POST
Archivos con file_put_contents ¦ file_put_contents ¦ funciones para leer y escribir archivos ¦ guardar un registro de visitas ¦ <?php⏎$f = sys_get_temp_dir() . "/visitas.txt";⏎file_put_contents($f, "visita\n", FILE_APPEND);⏎echo count(file($f)) > 0 ? "guardado" : "vacío"; ¦ agrega una línea al archivo ¦ olvidar FILE_APPEND y borrar lo anterior
Composer ¦ composer require ¦ gestor de dependencias de PHP ¦ instalar librerías en tu proyecto ¦ <?php⏎// composer require monolog/monolog⏎// require __DIR__ . "/vendor/autoload.php";⏎echo "composer"; ¦ instala y carga librerías ¦ subir la carpeta vendor al repositorio
Autoload PSR-4 ¦ autoload ¦ carga automática de clases según su carpeta ¦ no escribir require para cada clase ¦ <?php⏎// composer.json: "autoload": { "psr-4": { "App\\": "src/" } }⏎// use App\Modelos\Usuario;⏎echo "psr-4"; ¦ carga las clases de src automáticamente ¦ no coincidir el namespace con la carpeta
Laravel ¦ Route::get ¦ framework completo para crear aplicaciones web ¦ hacer una app con rutas, vistas y base de datos ¦ <?php⏎// Route::get('/hola', fn () => view('hola', ['nombre' => 'Ana']));⏎echo "Laravel"; ¦ crea una ruta con vista ¦ poner toda la lógica en las rutas
Eloquent ¦ Eloquent ¦ ORM de Laravel para trabajar con tablas como objetos ¦ consultar productos sin escribir SQL ¦ <?php⏎// $caros = Producto::where('precio', '>', 100)->orderBy('precio')->get();⏎echo "Eloquent"; ¦ consulta productos caros ordenados ¦ hacer una consulta por cada fila de una lista
Blade ¦ {{ }} ¦ motor de plantillas de Laravel ¦ mostrar datos en HTML de forma segura ¦ <?php⏎// <h1>Hola {{ $nombre }}</h1>⏎// @foreach ($productos as $p) <li>{{ $p->nombre }}</li> @endforeach⏎echo "Blade"; ¦ muestra variables escapadas en la vista ¦ usar {!! !!} con datos del usuario
Pruebas con PHPUnit ¦ assertEquals ¦ framework de pruebas automáticas de PHP ¦ comprobar que una función funciona ¦ <?php⏎// public function testSuma(): void { $this->assertEquals(5, sumar(2, 3)); }⏎function sumar($a, $b) { return $a + $b; }⏎echo sumar(2, 3) === 5 ? "ok" : "falla"; ¦ prueba la suma ¦ probar solo los casos felices
Variables de entorno en PHP ¦ getenv ¦ forma de leer configuración secreta fuera del código ¦ guardar la clave de la base de datos ¦ <?php⏎$clave = getenv("DB_PASS") ?: "sin clave";⏎echo $clave === "sin clave" ? "Define DB_PASS" : "ok"; ¦ lee la clave de una variable de entorno ¦ escribir contraseñas en el código
Errores y registros ¦ error_log ¦ funciones para registrar errores sin mostrarlos al usuario ¦ guardar los fallos en un archivo ¦ <?php⏎ini_set("display_errors", "0");⏎error_log("Pago falló para el pedido 17");⏎echo "registrado"; ¦ registra el error sin mostrarlo ¦ dejar display_errors activo en producción
Servidor de desarrollo ¦ php -S ¦ servidor web incluido en PHP para probar ¦ ver tu proyecto sin instalar Apache ¦ <?php⏎// php -S localhost:8000⏎echo "Abre http://localhost:8000"; ¦ inicia un servidor local ¦ usar el servidor de desarrollo en producción
Proyecto final con PHP ¦ index.php ¦ app completa con formularios, sesiones y base de datos ¦ practicar todo lo aprendido ¦ <?php⏎$tareas = [["t" => "Estudiar PHP", "hecha" => false]];⏎foreach ($tareas as $t) echo ($t["hecha"] ? "✔" : "•"), " ", htmlspecialchars($t["t"]), "\n"; ¦ muestra una lista de tareas ¦ mezclar SQL, HTML y lógica en un solo archivo
""")

